from qb import q, write

TL = ["backend-developer", "full-stack-developer", "python-developer", "data-scientist"]
ITEMS = [
    q("enterprise", "easy", ["sdlc"], "What is the difference between functional and non-functional requirements? Give two examples of each for a banking portal.", "Functional requirements say what the system does, such as transferring money or showing a statement. Non-functional requirements describe qualities such as response time under load, availability, security and audit logging.", ["What vs how well", "Examples of each", "Both need testing"], ["How do you test a non-functional requirement?"]),
    q("enterprise", "medium", ["architecture"], "What is a layered architecture and why do enterprise applications separate presentation, business logic and data access?", "Layers separate concerns so the user interface, business rules and database code can change and be tested independently. The rules sit in one place, which avoids duplication and makes the system easier to maintain.", ["Separation of concerns", "Business rules in one place", "Independent change and testing"], ["What goes wrong when business logic lives in the UI?"]),
    q("enterprise", "hard", ["integration"], "Two enterprise systems need to exchange data daily. Compare file transfer, an API and a message queue.", "Files are simple but slow and hard to validate in real time, an API gives immediate request and response, and a queue decouples systems and survives outages. Choose by volume, timing, reliability and the ability of both teams to maintain it.", ["Three integration styles", "Timing and reliability trade-offs", "Choose by needs"], ["How would you monitor the integration?"]),
    q("enterprise", "medium", ["security"], "What is role-based access control and how would you apply it in an internal HR application?", "Users are assigned roles and roles carry permissions, so an employee sees their own data, a manager sees their team's and HR sees everyone. Check permissions on the server for every request and log sensitive access.", ["Roles carry permissions", "Server-side checks", "Audit sensitive access"], ["How do you handle someone with two roles?"]),
    q("csharp", "medium", ["dotnet"], "How would you structure a .NET solution with a Web API, business logic, data access and tests?", "Use separate projects for the API, the domain or services, data access and tests, with dependencies pointing inward and injected through interfaces. Configuration and secrets live outside the code.", ["Separate projects", "Dependencies point inward", "Interfaces and injection"], ["Why avoid referencing the data project from the API directly?"]),
    q("csharp", "hard", ["async"], "What is a deadlock caused by blocking on async code and how do you avoid it?", "Blocking on a Task with .Result or .Wait in a context that needs to resume on the same thread can make each wait for the other forever. Avoid it by using await throughout and not mixing blocking and async code.", ["Blocking an async call", "Context waits for itself", "Async all the way"], ["How does ConfigureAwait relate to this?"]),
    q("sql", "easy", ["sql"], "What is the difference between UNION and UNION ALL, and between DELETE and TRUNCATE?", "UNION combines results and removes duplicates, which costs extra work, while UNION ALL keeps all rows and is faster. DELETE removes chosen rows and can be rolled back with logging, and TRUNCATE quickly empties a table.", ["Duplicate removal", "Cost difference", "DELETE vs TRUNCATE"], ["When is UNION the correct choice?"]),
    q("sql", "medium", ["design"], "How would you design tables for employees, departments and managers where a manager is also an employee?", "Use an employees table with a department foreign key and a manager_id that references the employee's own table, a self-referencing relationship. Add constraints and an index on the manager column.", ["Self-referencing foreign key", "Department link", "Constraints and index"], ["How do you query the full reporting chain?"]),
    q("sql", "hard", ["transactions"], "What is a deadlock in a database and how do you reduce them?", "A deadlock happens when two transactions each hold a lock the other needs, and the database aborts one. Reduce them by accessing tables in a consistent order, keeping transactions short and indexed and retrying the aborted one.", ["Circular lock waits", "Consistent order and short transactions", "Retry the victim"], ["How do you find which queries deadlock?"]),
    q("data", "medium", ["warehouse"], "What is a data warehouse and how does it differ from the operational database?", "A warehouse stores historical, cleaned data from many systems organised for analysis and reporting, while an operational database supports day-to-day transactions with fast small reads and writes. Keeping them separate protects the live system from heavy reports.", ["Analytics vs transactions", "Historical, integrated data", "Protects the live system"], ["What is a data mart?"]),
    q("data", "hard", ["quality"], "How would you find and fix inconsistent customer records that come from three different systems?", "Profile the data, define matching rules using keys such as email or national id and fuzzy matching on names, decide which source wins for each field, merge with an audit trail and add validation at the source. Review uncertain matches manually.", ["Profile and match", "Survivorship rules", "Audit and prevent at source"], ["How do you avoid merging two different people?"]),
    q("data", "medium", ["python-data"], "How would you use Python to produce a weekly report from several CSV exports and email it?", "Read the files with pandas, validate and clean them, aggregate with groupby, write the output to a file or HTML table and send it with the email library or a service, scheduled through a job scheduler with logging and failure alerts.", ["Validate and aggregate", "Generate the report", "Schedule, log and alert"], ["How would you test it?"]),
    q("cloud", "medium", ["cloud"], "What would you consider when moving an on-premises application to the cloud?", "Check dependencies, data size and sensitivity, compliance and latency, choose between lifting as is and redesigning, plan migration steps with rollback, set up security and cost monitoring and train the team.", ["Dependencies and compliance", "Migration strategy", "Cost and security monitoring"], ["What would you not move first?"]),
    q("cloud", "hard", ["resilience"], "How do you design an internal application so that a database outage does not take down every feature?", "Separate critical from optional features, use timeouts and circuit breakers, cache read-only data, degrade gracefully with clear messages, add replicas and failover and practise recovery with backups.", ["Graceful degradation", "Timeouts and circuit breakers", "Replicas, failover, backups"], ["How do you decide which features are critical?"]),
    q("api", "medium", ["rest"], "How do you secure and document an internal REST API used by several teams?", "Authenticate with tokens, authorise by role, validate input, rate limit and log, and publish an OpenAPI specification with examples and a changelog so teams can integrate without guessing. Version breaking changes.", ["Authentication and authorisation", "OpenAPI documentation", "Versioning"], ["How do you keep the documentation correct?"]),
    q("api", "medium", ["performance"], "An internal report API times out when the date range is large. What do you do?", "Add indexes and optimise the query, limit the range or paginate, pre-aggregate summaries, run large reports asynchronously and return a link when ready, and cache repeated requests.", ["Optimise the query", "Paginate or limit", "Asynchronous large reports"], ["How would you tell the user a report is still running?"]),
    q("oop", "medium", ["patterns"], "Explain the factory and dependency injection ideas and why enterprise code uses them.", "A factory creates objects without the caller naming the concrete class, and dependency injection supplies the needed objects from outside. Both reduce coupling, so implementations can be swapped and tested.", ["Create without naming the class", "Supply dependencies from outside", "Lower coupling"], ["Show how this helps a unit test."]),
    q("testing", "medium", ["uat"], "What is user acceptance testing and how do you support it as a developer?", "UAT lets real users confirm the system meets business needs before release. A developer helps by preparing a realistic test environment and data, writing clear release notes, fixing issues quickly and tracking sign-off.", ["Business confirms the system", "Realistic environment and data", "Track issues and sign-off"], ["What do you do when users find a requirement was misunderstood?"]),
    q("testing", "easy", ["unit-testing"], "What are the qualities of a good unit test and what should you not test?", "A good unit test is fast, isolated, repeatable and checks one behaviour with a clear name. Do not test the framework or trivial getters, and avoid tests that depend on the network or the clock.", ["Fast, isolated, repeatable", "One behaviour", "Skip trivial code"], ["What is a test double?"]),
    q("tl-scenario", "medium", ["debugging"], "Scenario: payroll calculation gives the wrong amount for a few employees only. How do you investigate?", "Compare the affected employees for a pattern such as grade, leave or date, reproduce with their data in a test environment, trace the calculation step by step, fix the rule and add tests for that case, and correct the affected records with an audit trail.", ["Find the pattern", "Reproduce and trace", "Fix, test and correct data"], ["How would you tell the affected employees?"], kind="scenario"),
    q("tl-scenario", "hard", ["design"], "Scenario: design a workflow system where a leave request needs approval from a manager and then HR, with reminders and an audit trail.", "Model requests with a status and a history table, define allowed transitions, notify approvers and send reminders from a scheduler, enforce permissions per step and record who did what and when. Handle absent approvers with delegation.", ["Status and transition rules", "Reminders and permissions", "Audit and delegation"], ["How do you handle a request while the policy changes?"], kind="scenario"),
    q("tl-scenario", "easy", ["teamwork"], "Scenario: the requirements are unclear and the business owner is busy. How do you move forward?", "Write down your understanding and assumptions, ask short specific questions, build a small prototype to get feedback and record decisions so the work does not stall or drift.", ["Document assumptions", "Short specific questions", "Prototype for feedback"], ["How do you handle a change after delivery?"], kind="scenario"),
    q("git", "easy", ["git"], "What is a good branching and release process for an enterprise team with a staging and a production environment?", "Develop on feature branches, merge through reviewed pull requests, deploy to staging for testing and promote the tagged build to production with a rollback plan. Keep hotfix branches for urgent fixes.", ["Feature branches and reviews", "Staging before production", "Tags and hotfixes"], ["How do you avoid deploying untested code?"]),
    q("python", "easy", ["python"], "How would you read a file of employee records, skip invalid lines and report how many were skipped, in Python?", "Open the file with a context manager, loop over lines, validate each with try and except or explicit checks, collect valid records, count the skipped ones and log the reasons. Process in a streaming way for large files.", ["Context manager and loop", "Validate and count skipped", "Log reasons"], ["How would you write the valid records to a new file?"]),
    q("project", "easy", ["projects"], "Describe a project with several parts, such as a database, an API and a report. What did you design yourself and how did you handle bad data?", "A strong answer explains the structure and your own design choices, how you validated and cleaned data, one problem and its fix and how you tested the whole thing.", ["Own design", "Validation and cleaning", "Problem and fix"], ["What would you refactor?"], kind="scenario", roles=TL + ["frontend-developer"]),
]


def build():
    return write("techlogix", TL, ITEMS)


if __name__ == "__main__":
    build()
